#include "placer/optimizer/NonsmoothOptimizer.hpp"
#include "placer/multilevel/Projector.hpp"
#include <cmath>
namespace placer { static double rms(const std::vector<double>&x,const std::vector<double>&y,const Level&l){double s=0;size_t n=0;for(size_t i=0;i<l.objects.size();++i)if(!l.objects[i].fixed){s+=x[i]*x[i]+y[i]*y[i];++n;}return n?std::sqrt(s/(2*n)):0;} OptimizeResult optimizeLevel(Level&l,const Region&r,const DensityGrid&dg,const OptimizeConfig&cfg){OptimizeResult out; auto we=wirelengthSubgradient(l,cfg.mode); auto de=dg.evaluate(l); double wr=rms(we.gx,we.gy,l), dr=rms(de.gx,de.gy,l); out.lambda=cfg.density_only?1:(cfg.lambda0>0?cfg.lambda0:(dr<EPS||de.penalty<EPS?1:std::min(1e8,std::max(1e-8,cfg.density_gradient_ratio*wr/dr)))); int glob=0; for(int st=0;st<cfg.penalty_stages;++st){for(int it=0;it<cfg.iterations_per_stage && glob<cfg.nmax;++it,++glob){we=wirelengthSubgradient(l,cfg.mode); de=dg.evaluate(l); double step=std::max(cfg.s_floor,(cfg.s0>0?cfg.s0:std::max(1.0,r.xh-r.xl)/100.0)/(1.0+glob/std::max(EPS,cfg.step_decay))); HistoryRow row; row.global_iteration=glob; row.level=cfg.level_index; row.stage=st; row.iteration=it; row.hpwl=we.hpwl; row.density_penalty=de.penalty; row.ofr_penalty=de.ofr_penalty; row.ofr_report=de.ofr_report; row.max_density=de.max_density; row.overflow_bins_penalty=de.overflow_bins_penalty; row.overflow_bins_report=de.overflow_bins_report; row.lambda=out.lambda; row.step=step; row.gradient_rms=rms(we.gx,we.gy,l); row.total_norm=row.gradient_rms; out.history.push_back(row); if(cfg.target_ofr>0 && de.ofr_report<=cfg.target_ofr)break; for(size_t i=0;i<l.objects.size();++i)if(!l.objects[i].fixed){double gx=cfg.density_only?de.gx[i]:we.gx[i]+out.lambda*de.gx[i]; double gy=cfg.density_only?de.gy[i]:we.gy[i]+out.lambda*de.gy[i]; l.objects[i].x-=step*gx/std::max(EPS,row.gradient_rms); l.objects[i].y-=step*gy/std::max(EPS,row.gradient_rms);} projectLevel(l,r);} out.lambda*=cfg.lambda_growth_low;} auto fe=dg.evaluate(l); out.hpwl=exactHpwl(l); out.density_penalty=fe.penalty; out.ofr_penalty=fe.ofr_penalty; out.ofr_report=fe.ofr_report; out.max_density=fe.max_density; return out;} }
